public void RememberConfigurationParameters(string module,string node,IReadOnlyDictionary<string,JsonElement> before,IReadOnlyDictionary<string,JsonElement> after,bool reset=false){var state=Parameters(module,node);lock(state.Gate){if(state.Values is null&&!reset)return;state.Seed??=before.ToDictionary(p=>p.Key,p=>p.Value.Clone());state.Values??=new();foreach(var pair in after)if(reset||!before.TryGetValue(pair.Key,out var old)||old.GetRawText()!=pair.Value.GetRawText()){state.Seed[pair.Key]=pair.Value.Clone();state.Values[pair.Key]=pair.Value.Clone();}}}

private void ExchangeBuffer(bool isSpare = false)
{
	if (isSpare)
	{
		Dictionary<string, ImageData> dictionary = displayImageStore;
		Dictionary<object, object> dictionary2 = displayShapeStore;
		displayImageStore = spareImageStore;
		displayShapeStore = spareShapeStore;
		spareImageStore = dictionary;
		spareShapeStore = dictionary2;
	}
	else
	{
		Dictionary<string, ImageData> dictionary3 = displayImageStore;
		Dictionary<object, object> dictionary4 = displayShapeStore;
		displayImageStore = bufferImageStore;
		displayShapeStore = bufferShapeStore;
		bufferImageStore = dictionary3;
		bufferShapeStore = dictionary4;
	}
}

